-- ============================================================
-- Superior Training: wiring
-- ============================================================
--
-- TODO.md: "Improved Mend Pet (Renamed to Superior Training) (1, 3): When your
-- pet is attacked it has a 50%/100% chance to bite back, dealing damage to all
-- enemies within 8 yards. If your pet hasn't been attacked for more than 8
-- seconds it gains Well-Trained, increasing its damage by 10% (2 ranks)"
--
-- The talent no longer does anything on the hunter, so core's own proc row has
-- to go -- it would keep firing the retail dispel behaviour off Mend Pet ticks
-- against a talent whose effects no longer describe that.
DELETE FROM `spell_proc` WHERE `SpellId` = -19572;

DELETE FROM `spell_pet_auras` WHERE `spell` IN (19572, 19573);
INSERT INTO `spell_pet_auras` (`spell`, `effectId`, `pet`, `aura`) VALUES
(19572, 0, 0, 200750),
(19573, 0, 0, 200751);

-- ProcFlags 0x00100028
--   0x00000008 PROC_FLAG_TAKEN_MELEE_AUTO_ATTACK
--   0x00000020 PROC_FLAG_TAKEN_SPELL_MELEE_DMG_CLASS
--   0x00100000 PROC_FLAG_TAKEN_DAMAGE
-- TAKEN_*, because for this talent the pet is the victim rather than the actor.
--
-- Cooldown 1500 is load-bearing.  A tank pet holding six mobs takes something
-- like six swings a second; an unthrottled 8-yard AoE retaliation on each is
-- both a damage explosion and -- with the x2.00 threat aura from
-- woa_2026_08_11_07.sql on top -- a threat one.  The ICD makes it a steady
-- trickle instead.
--
-- Two rows because the 50/100% split lives in Chance and spell_proc is keyed by
-- spell id.
DELETE FROM `spell_proc` WHERE `SpellId` IN (200750, 200751);
INSERT INTO `spell_proc` (`SpellId`, `SchoolMask`, `SpellFamilyName`, `SpellFamilyMask0`, `SpellFamilyMask1`, `SpellFamilyMask2`, `ProcFlags`, `SpellTypeMask`, `SpellPhaseMask`, `HitMask`, `AttributesMask`, `DisableEffectsMask`, `ProcsPerMinute`, `Chance`, `Cooldown`, `Charges`) VALUES
(200750, 0, 0, 0, 0, 0, 1048616, 0, 2, 0, 0, 0, 0, 50, 1500, 0),
(200751, 0, 0, 0, 0, 0, 1048616, 0, 2, 0, 0, 0, 0, 100, 1500, 0);

-- 200752 copies 200739's targeting exactly: TARGET_SRC_CASTER (22) +
-- TARGET_UNIT_SRC_AREA_ENEMY (15) with radius index 14 (8 yd), the same
-- selection Whirlwind (1680) uses.  IGNORE_ARMOR for the same reason as the
-- other pre-computed payloads -- the amount handed in is already one mitigated
-- pet swing, and Unit::IsDamageReducedByArmor would tax it twice.
DELETE FROM `spell_custom_attr` WHERE `spell_id` = 200752;
INSERT INTO `spell_custom_attr` (`spell_id`, `attributes`) VALUES
(200752, 0x8000);

-- Well-Trained's EffectMiscValue is 127, not 1, for exactly the reason
-- woa_2026_08_11_07.sql spells out: a physical-only mask would leave every
-- elemental pet ability out of the bonus.  Its +10% multiplies against the
-- global -20%, giving 0.88x baseline rather than 0.90x, which is the correct
-- multiplicative reading.
DELETE FROM `spell_script_names` WHERE `spell_id` IN (200750, 200751);
INSERT INTO `spell_script_names` (`spell_id`, `ScriptName`) VALUES
(200750, 'spell_hun_superior_training'),
(200751, 'spell_hun_superior_training');
